INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(40011, 'Genesis 42:32', 'Genesis', 42, 32, 'مونږ دولس ورونه او د یو پلار زامن یو. زمونږ یو ورور مړ شوی دی او کشر ورور مو په کنعان کې زمونږ د پلار سره دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis42_verse_32.mp3', '', 1761754199, 1761754199),
(40012, 'Genesis 42:33', 'Genesis', 42, 33, 'د مصر دوهم مشر په ځواب کې وویل: ‹هغه وخت به زه پوه شم چې تاسو صادقان یئ چې د خپلو ورونو څخه یو دلته زما سره پرېږدئ او د خپلو وږیو کورنیو دپاره غله واخلئ او لاړ شئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis42_verse_33.mp3', '', 1761754199, 1761754199),
(40013, 'Genesis 42:34', 'Genesis', 42, 34, 'خو خپل کشر ورور ماته راولئ، نو زه به پوه شم چې تاسو جاسوسان نه یئ، بلکې صادقان یئ. بیا به هغه وخت تاسو ته خپل ورور بېرته درکړم او تاسو به وکولای شئ چې دلته پاتې شئ او سوداګري وکړئ.›»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis42_verse_34.mp3', '', 1761754199, 1761754199),
(40014, 'Genesis 42:35', 'Genesis', 42, 35, 'نو څنګه چې هغوی خپلې بوجۍ خالي کړې، د هر کس په بوجۍ کې د هغه د پیسو کڅوړه وه. کله چې هغوی او د هغوی پلار د پیسو کڅوړې ولیدلې، نو ووېرېدل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis42_verse_35.mp3', '', 1761754199, 1761754199),
(40015, 'Genesis 42:36', 'Genesis', 42, 36, 'د هغوی پلار یعقوب هغوی ته وویل: «تاسو زه د خپلو اولادونو څخه بې‌برخې کړم، یوسف نور نشته او شمعون هم نور نشته. اوس غواړئ چې بنیامین بوځئ. دا هرڅه زما سره کیږي!»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis42_verse_36.mp3', '', 1761754199, 1761754199),
(40016, 'Genesis 42:37', 'Genesis', 42, 37, 'په دې وخت کې روبین خپل پلار ته وویل: «که بنیامین مې بېرته تاته رانه‌ووست، زما دواړه زامن ووژنه. هغه ماته وسپاره زه به یې بېرته راولم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis42_verse_37.mp3', '', 1761754199, 1761754199),
(40017, 'Genesis 42:38', 'Genesis', 42, 38, 'خو یعقوب وویل: «زما زوی به تاسو سره هلته نه ځي. د هغه ورور مړ شوی دی او هغه یوازې پاتې دی. که چېرې په لاره کې په هغه باندې څه پېښه وشي، نو زه زوړ سړی یم، له غمه به مړ شم او تاسو ټول به ملامته شئ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis42_verse_38.mp3', '', 1761754199, 1761754199),
(40018, 'Ezekiel 19:1', 'Ezekiel', 19, 1, 'څښتن ماته وویل چې د اسراییلو د دوو پاچاهانو دپاره دا د ویر سندره ووایم:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel19_verse_1.mp3', '', 1761754199, 1761754199),
(40019, 'Ezekiel 19:2', 'Ezekiel', 19, 2, '«څنګه مور دې درلودله؟ هغه وه یوه زمرۍ! څملاستله د زمریانو منځ کې هغې کړل لوی خپل بچیان ځوانو زمریو منځ کې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel19_verse_2.mp3', '', 1761754199, 1761754199),
(40020, 'Ezekiel 19:3', 'Ezekiel', 19, 3, 'هغې لوی کړ یو بچی او د هغه نه جوړ شو یو قوي زمری او هغه زده کړ د ښکار چل او خوړل به یې انسانان', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel19_verse_3.mp3', '', 1761754199, 1761754199),
(40021, 'Ezekiel 19:4', 'Ezekiel', 19, 4, 'واورېدل نورو قومونو د هغه په هکله هغه یې راګېر کړ په خپلې کنده کې مصر ته یې بوتلو په چنګکونو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel19_verse_4.mp3', '', 1761754199, 1761754199),
(40022, 'Ezekiel 19:5', 'Ezekiel', 19, 5, 'مور یې وویست انتظار هغه دپاره چې راستون شي خو امیدونه یې ټول له لاسه ورکړل بیا هغې لوی کړلو خپل بل بچی او هغه یې جوړ کړ یو قوي زمری', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel19_verse_5.mp3', '', 1761754199, 1761754199),
(40023, 'Ezekiel 19:6', 'Ezekiel', 19, 6, 'چې کله ښه لوی شو نو ګرځېده راګرځېده هغه نورو زمریانو سره هغه هم زده کړل چې ښکار وکړي او وخوري انسانان', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel19_verse_6.mp3', '', 1761754199, 1761754199),
(40024, 'Ezekiel 19:7', 'Ezekiel', 19, 7, 'هغه چپه کړې کلاګانې او ښارونه یې وران کړل چې به کله غړمبېدلو هغه نو هغه هېواد او ټول خلک به یې وېرېدل له هغه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel19_verse_7.mp3', '', 1761754199, 1761754199),
(40025, 'Ezekiel 19:8', 'Ezekiel', 19, 8, 'شول راټول سره قومونه چې جګړه ورسره وکړي خلک راغلل له شاوخوا ولایتونو څخه هغوی خپور کړ په هغه باندې خپل جال او په خپله کنده کې یې راګېر کړ هغه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel19_verse_8.mp3', '', 1761754199, 1761754199),
(40026, 'Ezekiel 19:9', 'Ezekiel', 19, 9, 'هغه ته یې واچوله حلقه د اوسپنې او هغه یې یووړ د بابل پاچا ته په زندان کې یې بندي کړ هغه چې بیا وانه ورېدل شي غورېدل د هغه د اسراییلو په غرونو باندې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel19_verse_9.mp3', '', 1761754199, 1761754199),
(40027, 'Ezekiel 19:10', 'Ezekiel', 19, 10, 'وه ستا مور د انګورو د تاک په شان چې کرل شوی د ویالې په غاړه ځکه چې هلته وې پرېمانه اوبه هغه تاک ډک ؤ له مېوو او څانګو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel19_verse_10.mp3', '', 1761754199, 1761754199),
(40028, 'Ezekiel 19:11', 'Ezekiel', 19, 11, 'وې قوي د هغه څانګې او ورڅخه جوړه شوه شاهي امسا هغه شو لوړ د نورو ونو څخه ټولو لیدل چې څومره لوړ دی او ډک د څانګو څخه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel19_verse_11.mp3', '', 1761754199, 1761754199),
(40029, 'Ezekiel 19:12', 'Ezekiel', 19, 12, 'خو له بېخه وویستل شو تاک له ډېره قهره او راګوزار شولو په ځمکه باندې د ختیځ باد یې کړلې وچې مېوې قوي څانګه یې شوه وچه او وسوځېدله اور کې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel19_verse_12.mp3', '', 1761754199, 1761754199),
(40030, 'Ezekiel 19:13', 'Ezekiel', 19, 13, 'تاک کرل شوی اوس په دښته کې په بې‌اوبو او وچه ځمکه کې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel19_verse_13.mp3', '', 1761754199, 1761754199),
(40031, 'Ezekiel 19:14', 'Ezekiel', 19, 14, 'اور لګېدلی په تنه کې د تاک او سوځولې یې دي څانګې او مېوې د هغه هېڅ قوي څانګه په هغه کې پاتې شوې نه ده چې ورنه جوړه شي شاهي امسا» دا د ویر سندره ده او د ویر په توګه کارول شوې ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel19_verse_14.mp3', '', 1761754199, 1761754199),
(40032, 'Isaiah 22:1', 'Isaiah', 22, 1, 'دا پیغام د رویا د درې په هکله دی. څه خبره ده؟ ولې د ښار ټول خلک بامونو ته ختلي او خوشحالي کوي؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah22_verse_1.mp3', '', 1761754199, 1761754199),
(40033, 'Isaiah 22:2', 'Isaiah', 22, 2, 'ټول ښار له غوغا، شورماشور او خوښۍ څخه ډک دی. د دې ښار خلک ووژل شول، خو هغوی په توره یا په جګړه کې نه دي وژل شوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah22_verse_2.mp3', '', 1761754199, 1761754199),
(40034, 'Isaiah 22:3', 'Isaiah', 22, 3, 'ستاسو ټول مشران وتښتېدل او مخکې له دې چې حتی یو غشی هم ګوزار کړي هغوی ونیول شول. پروا نه لري چې څومره لېرې وتښتېدل، هغوی ټول ونیول شول او اسیران شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah22_verse_3.mp3', '', 1761754199, 1761754199),
(40035, 'Isaiah 22:4', 'Isaiah', 22, 4, 'اوس ما یوازې پرېږدئ چې د خپل قوم د بربادۍ په خاطر سخت وژاړم او ماته د تسلۍ راکولو کوښښ مه کوئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah22_verse_4.mp3', '', 1761754199, 1761754199),
(40036, 'Isaiah 22:5', 'Isaiah', 22, 5, 'په رښتیا مطلق قادر څښتن خدای هغه ورځ غوره کړې ده چې د رویا په دره کې خلک له ډار، ماتې او وارخطایۍ سره مخامخ شي. په هغه ورځ به د ښار دېوالونه راوغورځول شي او د ژړا او مرستې اوازونه به یې په غرونو کې واورېدل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah22_verse_5.mp3', '', 1761754199, 1761754199),
(40037, 'Isaiah 22:6', 'Isaiah', 22, 6, 'د عیلام د هېواد عسکر چې په لیندو او غشو سمبال، په اسونو او جنګي ګاډیو باندې سپاره وو او د قیر د هېواد عسکر سپرونه په لاس تیار وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah22_verse_6.mp3', '', 1761754199, 1761754199),
(40038, 'Isaiah 22:7', 'Isaiah', 22, 7, 'ستاسو ډېرې ښې درې د دښمن له جنګي ګاډیو ډکې شوې دي او په اسونو باندې سپاره سرتېري د اورشلیم د ښار د دروازو په مخکې قطار ولاړ دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah22_verse_7.mp3', '', 1761754199, 1761754199),
(40039, 'Isaiah 22:8', 'Isaiah', 22, 8, 'څښتن د یهودا دفاعي قواوې له منځه یوړې. په هغه ورځ، تاسو د وسلو د راوړلو دپاره سلاح کوټ ته لاړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah22_verse_8.mp3', '', 1761754199, 1761754199),
(40040, 'Isaiah 22:12', 'Isaiah', 22, 12, 'په هغه ورځ مطلق قادر څښتن خدای تاسو ته بلنه درکړه چې وژاړئ او ویر وکړئ، خپل سرونه وخرایئ او د ویر کالي واغوندئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah22_verse_12.mp3', '', 1761754199, 1761754199),
(40041, 'Isaiah 22:13', 'Isaiah', 22, 13, 'خو د دې په ځای تاسو د خوښۍ جشن جوړ کړ. تاسو غویان او پسونه حلال کړل چې ویې خورئ او شراب مو وڅښل. تاسو وویل: «راځئ چې وخورو او وڅښو، ځکه چې سبا ته مړه کېږو.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah22_verse_13.mp3', '', 1761754199, 1761754199),
(40042, 'Isaiah 22:14', 'Isaiah', 22, 14, 'مطلق قادر څښتن په خپله زما سره خبرې وکړې او ویې ویل: «ترڅو پورې چې تاسو ژوندي یئ په رښتیا به ستاسو دا ګناه ونه بخښل شي. دا زما یعنې مطلق قادر څښتن خدای خبره ده.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah22_verse_14.mp3', '', 1761754199, 1761754199),
(40043, 'Isaiah 22:15', 'Isaiah', 22, 15, 'مطلق قادر څښتن خدای ماته داسې وویل چې شبنا ته چې د پاچا د دربار د چارو مسوول دی، ورشه او هغه ته ووایه:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah22_verse_15.mp3', '', 1761754199, 1761754199),
(40044, 'Isaiah 22:16', 'Isaiah', 22, 16, '«ته دلته څه کوې؟ ته څه حق لرې چې د تیږو د غونډیو په اوچت ځای کې د خپل ځان دپاره قبر جوړوې؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah22_verse_16.mp3', '', 1761754199, 1761754199),
(40045, 'Isaiah 22:17', 'Isaiah', 22, 17, 'ګوره! که ته هرڅومره مهم سړی اوسې، خو څښتن به تا ټینګ راونیسي او لېرې به دې وغورځوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah22_verse_17.mp3', '', 1761754199, 1761754199),
(40046, 'Isaiah 22:18', 'Isaiah', 22, 18, 'هغه به تا د توپ په شان تاو او راتاو کړي او بیا به دې یو ډېر لېرې هېواد ته ګوزار کړي. ته به د خپلو هغو جنګي ګاډیو په څنګ کې چې تا ورباندې ویاړ کاوه، مړ شې. ته د خپل بادار د کورنۍ د رسوایۍ سبب یې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah22_verse_18.mp3', '', 1761754199, 1761754199),
(40047, 'Isaiah 22:19', 'Isaiah', 22, 19, 'نو څښتن به ستا څخه دا دنده او لوړ مقام واخلي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah22_verse_19.mp3', '', 1761754199, 1761754199),
(40048, 'Isaiah 22:20', 'Isaiah', 22, 20, 'څښتن شبنا ته وویل: «نو زه به په هغه ورځ خپل خدمتګار د حلقیا زوی الیاقیم راوغواړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah22_verse_20.mp3', '', 1761754199, 1761754199),
(40049, 'Isaiah 22:21', 'Isaiah', 22, 21, 'زه به ستا چپنه هغه ته ورواغوندم، ستا کمربند به د هغه په ملا باندې وتړم او هغه ټول واک چې تا درلود هغه به الیاقیم ته ورکړم. هغه به د اورشلیم او یهودا خلکو ته د پلار په شان وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah22_verse_21.mp3', '', 1761754199, 1761754199),
(40050, 'Isaiah 22:22', 'Isaiah', 22, 22, 'زه به هغه ته د داود د پاچاهۍ د دربار کیلي ورکړم. هغه چې کومه دروازه خلاصه کړي، نو څوک نه شي کولای چې هغه وتړي او کومه دروازه چې هغه تړلې ده، هېڅوک به نه شي کولای چې هغه خلاصه کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah22_verse_22.mp3', '', 1761754199, 1761754199),
(40051, 'Isaiah 22:23', 'Isaiah', 22, 23, 'زه به هغه لکه د مېخ په شان په خپل مقام کې ټینګ کړم او هغه به د خپل پلار د کورنۍ دپاره د سرلوړۍ سبب وګرځي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah22_verse_23.mp3', '', 1761754199, 1761754199),
(40052, 'Isaiah 22:24', 'Isaiah', 22, 24, 'خو د هغه ټول خپلوان او اولاده به په هغه بار وي. هغوی به په ده باندې داسې راځوړند وي لکه لوښي، کاسې او کوزې چې په مېخ باندې ځوړندې وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah22_verse_24.mp3', '', 1761754199, 1761754199),
(40053, 'Isaiah 22:25', 'Isaiah', 22, 25, 'په هغه ورځ به هغه مېخ چې په خپل ځای باندې ټینګ ؤ هغه به سست شي او وبه غورځیږي. هرڅه چې په هغه باندې ځوړند وو، نو هغه به له منځه لاړ شي.» دا څښتن ویلي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah22_verse_25.mp3', '', 1761754199, 1761754199),
(40054, 'Songofsongs 1:1', 'Songofsongs', 1, 1, 'د حضرت سليمان خواږۀ سرودونه. محبوبه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/songofsongs1_verse_1.mp3', '', 1761754199, 1761754199),
(40055, 'Songofsongs 1:2', 'Songofsongs', 1, 2, 'بيا بيا مې په خپلو شونډو سره ښُکل کړه، ځکه چې ستا مينه د ميو نه زياته مزه کړينه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/songofsongs1_verse_2.mp3', '', 1761754199, 1761754199),
(40056, 'Songofsongs 1:3', 'Songofsongs', 1, 3, 'ستا د عطرو خوشبوئى څومره ښُکلې ده، ستا نوم لکه د هغې د خوشبو په شان ده. نو ځکه ټولې پېغلې په تا مئينې دينه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/songofsongs1_verse_3.mp3', '', 1761754199, 1761754199),
(40057, 'Songofsongs 1:4', 'Songofsongs', 1, 4, 'زر شه، ما د خپل ځان سره بوځه، تۀ زما بادشاه شه، ما خپلې کوټې ته بوځه. ښځې اے بادشاه مونږ څومره ستا دپاره خوشحاله يونه، د ميو نه زيات مونږ ستا د مينې صِفت کوونه. محبوبه دا رښتيا دى چې پېغلې په تا مئينې دينه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/songofsongs1_verse_4.mp3', '', 1761754199, 1761754199),
(40058, 'Songofsongs 1:5', 'Songofsongs', 1, 5, 'زۀ خو توره يمه خو ښُکلې يمه، اے د يروشلم جينکو، د قيدار د خېمو په شان توره يمه او د سليمان د خېمې د پردو په شان توره يمه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/songofsongs1_verse_5.mp3', '', 1761754199, 1761754199),
(40059, 'Songofsongs 1:6', 'Songofsongs', 1, 6, 'ما ته مۀ ګورئ ځکه چې زۀ غنم رنګه يمه، زما څرمنه نمر توره کړې ده. زما وروڼه ما سره وران وونه او په زبردستۍ سره هغوئ په ما د خپلو انګورو خيال ساتلو. نو بيا ما خپل خيال ونۀ ساتلو، او نۀ مې د خپل انګور خيال وکړلو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/songofsongs1_verse_6.mp3', '', 1761754199, 1761754199),
(40060, 'Songofsongs 1:7', 'Songofsongs', 1, 7, 'ما ته ووايه، زما جانانه، تۀ به نن خپله رمه څرولو له چرته بوځې؟ او تۀ خپلې ګډې په غرمه کښې د دمې دپاره چرته راغونډوې؟ نو بيا زۀ ولې برقعه په سر سرګردانه شمه او ستا د ملګرو په رمو کښې درپسې وګرځمه محبوب', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/songofsongs1_verse_7.mp3', '', 1761754199, 1761754199),
(40061, 'Songofsongs 1:8', 'Songofsongs', 1, 8, 'اے په ټولو پېغلو کښې ښائسته محبوبې، کۀ چرې تا ته دا پته نۀ وينه، نو د رمو د پښو ښاپونو پسې شه روانه، او خپل چېلى دې د شپانو د خېمو په خوا کښې وڅرونه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/songofsongs1_verse_8.mp3', '', 1761754199, 1761754199),
(40062, 'Songofsongs 1:9', 'Songofsongs', 1, 9, 'زما محبوبې، تۀ په ما دومره ګرانه ينه، لکه د فِرعون د شاهى آسپې په شان ښائسته ينه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/songofsongs1_verse_9.mp3', '', 1761754199, 1761754199),
(40063, 'Songofsongs 1:10', 'Songofsongs', 1, 10, 'ستا اننګى څومره ښائسته دينه، او هغه ستا د غوږونو والو سره ځليږينه. او ستا غړۍ څومره ښائسته ده، او د سرو سره څومره ښُکلې ښکارينه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/songofsongs1_verse_10.mp3', '', 1761754199, 1761754199),
(40064, 'Songofsongs 1:11', 'Songofsongs', 1, 11, 'خو مونږ به د سرو زرو والۍ درته او د سپينو زرو مرۍ جوړې کړونه. محبوبه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/songofsongs1_verse_11.mp3', '', 1761754199, 1761754199),
(40065, 'Songofsongs 1:12', 'Songofsongs', 1, 12, 'کله چې زما شهزاده خپل کټ کښې آرام کولونه، نو زما د عطرو په خوشبويۍ کښې نشه نشه شونه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/songofsongs1_verse_12.mp3', '', 1761754199, 1761754199),
(40066, 'Songofsongs 1:13', 'Songofsongs', 1, 13, 'زما جانان د مُر زونډے دېنه، زما په سينه پروت دېنه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/songofsongs1_verse_13.mp3', '', 1761754199, 1761754199),
(40067, 'Songofsongs 1:14', 'Songofsongs', 1, 14, 'زما جانان د عين‌جدى د انګورو په باغونو کښې د نکريزو د ګل په شان دېنه محبوب', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/songofsongs1_verse_14.mp3', '', 1761754199, 1761754199),
(40068, 'Songofsongs 1:15', 'Songofsongs', 1, 15, 'زما محبوبې، تۀ څومره ښائسته ينه. تۀ څومره حسينه ينه، سترګې دې د ګوګوشتکو په شان ښُکلې دينه. محبوبه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/songofsongs1_verse_15.mp3', '', 1761754199, 1761754199),
(40069, 'Songofsongs 1:16', 'Songofsongs', 1, 16, 'تۀ ډېر ښُکلے يې زما جانانه، تۀ څومره زړۀ وړونکے ينه، شنه ګياه به زمونږ بستره وينه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/songofsongs1_verse_16.mp3', '', 1761754199, 1761754199),
(40070, 'Songofsongs 1:17', 'Songofsongs', 1, 17, 'د دِيار لرګى به زمونږ د کور وى تيرونه، او د خوشبوداره دِيار لرګى زمونږ د کور دى تيرونه، او د دِيار ونه به زمونږ د کوټې چت وينه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/songofsongs1_verse_17.mp3', '', 1761754199, 1761754199),
(40071, 'Isaiah 15:1', 'Isaiah', 15, 1, 'د موآب په هکله پیغام: د موآب د عار او قیر ښارونه په یوه شپه کې ورانیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah15_verse_1.mp3', '', 1761754199, 1761754199),
(40072, 'Isaiah 15:2', 'Isaiah', 15, 2, 'د دیبون خلک غره ته ختلي دي چې په خپلو بتخانو کې وژاړي. د موآب خلک د نبو او میدیبا د ښارونو په خاطر له غمه ژړا او انګولا کوي. هغوی له غمه خپل سرونه او خپلې ږیرې خریلې دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah15_verse_2.mp3', '', 1761754199, 1761754199),
(40073, 'Isaiah 15:3', 'Isaiah', 15, 3, 'خلکو د ویر کالي اغوستي دي او د خپلو کورونو په بامونو او د ښار په چوکونو انګولا کوي او په چیغو چیغو ژاړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah15_verse_3.mp3', '', 1761754199, 1761754199),
(40074, 'Isaiah 15:4', 'Isaiah', 15, 4, 'د حشبون او العاله خلک چیغې وهي او د هغوی ژړاګانې تر یاهص اورېدل کیږي. په دې خاطر د موآب په وسلو سمبال عسکر چیغې وهي او له وېرې نه رپیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah15_verse_4.mp3', '', 1761754199, 1761754199),
(40075, 'Isaiah 15:5', 'Isaiah', 15, 5, 'زما زړه د موآب دپاره فریاد کوي! خلک د صوغر او عجلت شلیشه ښارونو ته تښتېدلي دي. ځینې خلک په ژړا کې لوحیت ته خېژي او ځینې د حورونایم په لار د خپل هېواد د ورانۍ په خاطر په چیغو چیغو ژاړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah15_verse_5.mp3', '', 1761754199, 1761754199),
(40076, 'Isaiah 15:6', 'Isaiah', 15, 6, 'د نمریم ویاله وچه شوې ده او د هغې په غاړه چې کوم واښه وو، هغه مړاوي شوي دي او هېڅ شین بوټی په کې نه دی پاتې شوی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah15_verse_6.mp3', '', 1761754199, 1761754199),
(40077, 'Isaiah 15:7', 'Isaiah', 15, 7, 'په دې خاطر خلک هڅه کوي ترڅو د ولې د ونو د درې نه د خپلې ټولې شتمنۍ سره په تېښته تېر شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah15_verse_7.mp3', '', 1761754199, 1761754199),
(40078, 'Isaiah 15:8', 'Isaiah', 15, 8, 'د موآب په سرحدونو کې په هرځای کې ژړاګانې اورېدل کیږي. حتی دا ژړاګانې او انګولاوې د اجلایم نه تر بیرایلیم پورې هم رسېدلې دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah15_verse_8.mp3', '', 1761754199, 1761754199),
(40079, 'Isaiah 15:9', 'Isaiah', 15, 9, 'په رښتیا د دیبون له ښار سره چې کوم سیند دی هغه په وینو باندې سور شوی دی او زه څښتن به د هغه ځای په خلکو باندې د دې نه ډېر بد مصیبت هم راولم. هو، په موآب کې چې څوک پاتې دي او یا د تښتېدو هڅه کوي، هغوی به په زمریو باندې ووژل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah15_verse_9.mp3', '', 1761754199, 1761754199),
(40080, 'Genesis 17:1', 'Genesis', 17, 1, 'هغه وخت چې ابرام د نهه نوي کالو په عمر ؤ، څښتن هغه ته ښکاره شو او ویې ویل: «زه مطلق قادر خدای یم. زما منونکی او بې‌ګناه اوسه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis17_verse_1.mp3', '', 1761754199, 1761754199),
(40081, 'Genesis 17:2', 'Genesis', 17, 2, 'زه به ستا سره یو لوظ وکړم او ډېره اولاده به درکړم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis17_verse_2.mp3', '', 1761754199, 1761754199),
(40082, 'Genesis 17:3', 'Genesis', 17, 3, 'نو هغه وخت ابرام هغه ته سجده وکړه او خدای هغه ته وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis17_verse_3.mp3', '', 1761754199, 1761754199),
(40083, 'Genesis 17:4', 'Genesis', 17, 4, '«ستا سره دا لوظ کوم چې ته به د ډېرو قومونو پلار شې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis17_verse_4.mp3', '', 1761754199, 1761754199),
(40084, 'Genesis 17:5', 'Genesis', 17, 5, 'له دې وروسته به ستا نوم ابرام نه، بلکې ابراهیم وي، ځکه چې ته مې د ډېرو قومونو پلار کړی یې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis17_verse_5.mp3', '', 1761754199, 1761754199),
(40085, 'Genesis 17:6', 'Genesis', 17, 6, 'زه به ستا نسل زیات کړم او ستا څخه به قومونه پیدا کړم او د هغوی څخه به ځینې پاچاهان شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis17_verse_6.mp3', '', 1761754199, 1761754199),
(40086, 'Genesis 17:7', 'Genesis', 17, 7, 'زه به خپل لوظ ستا، ستا د اولادې او ستا څخه وروسته ستا د راتلونکي نسل سره ټینګ وساتم او دا به ابدي لوظ وي. زه به ستا خدای یم او ستا څخه وروسته به ستا د اولادې خدای یم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis17_verse_7.mp3', '', 1761754199, 1761754199),
(40087, 'Genesis 17:8', 'Genesis', 17, 8, 'زه به د کنعان ټوله خاوره په کومه کې چې ته اوس مسافر یې، ستا څخه وروسته ستا اولادې ته د ابدي ملکیت په توګه ورکړم او زه به د هغوی خدای یم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis17_verse_8.mp3', '', 1761754199, 1761754199),
(40088, 'Genesis 17:9', 'Genesis', 17, 9, 'خدای ابراهیم ته وویل: «ته او ستا څخه وروسته ستا ټوله اولاده باید زما په لوظ باندې ټینګ ودرېږئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis17_verse_9.mp3', '', 1761754199, 1761754199),
(40089, 'Genesis 17:10', 'Genesis', 17, 10, 'ته او ستا اولاده باید سره موافقه وکړئ چې ستاسو هر یو نارینه دې سنت شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis17_verse_10.mp3', '', 1761754199, 1761754199),
(40090, 'Genesis 17:13', 'Genesis', 17, 13, 'هر یو کس باید سنت شي. دا به ستاسو په بدن باندې زما د ابدي لوظ نښه وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis17_verse_13.mp3', '', 1761754199, 1761754199),
(40091, 'Genesis 17:14', 'Genesis', 17, 14, 'هر یو نارینه چې سنت شوی نه وي باید زما د قوم څخه وشړل شي، ځکه چې هغه زما لوظ مات کړی دی.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis17_verse_14.mp3', '', 1761754199, 1761754199),
(40092, 'Genesis 17:15', 'Genesis', 17, 15, 'خدای ابراهیم ته وویل: «له دې وروسته خپلې ښځې ته سارای مه وایه، د هغې نوم دې له همدا‌اوس څخه ساره شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis17_verse_15.mp3', '', 1761754199, 1761754199),
(40093, 'Genesis 17:16', 'Genesis', 17, 16, 'زه به هغې ته برکت ورکړم او د هغې په وسیله به زوی درکړم. هغه به د قومونو مور شي او د هغې څخه به د قومونو پاچاهان راپیدا شي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis17_verse_16.mp3', '', 1761754199, 1761754199),
(40094, 'Genesis 17:17', 'Genesis', 17, 17, 'ابراهیم خدای ته سجده وکړه او ویې خندل او د خپل ځان سره یې وویل: «ایا د سل کلن سړي څخه به زوی پیدا شي؟ ایا ساره به په نوي کلنۍ کې ماشوم وزېږوي؟»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis17_verse_17.mp3', '', 1761754199, 1761754199),
(40095, 'Genesis 17:18', 'Genesis', 17, 18, 'ابراهیم خدای ته وویل: «اسماعیل ولې زما میراث خور نه شي؟»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis17_verse_18.mp3', '', 1761754199, 1761754199),
(40096, 'Genesis 17:19', 'Genesis', 17, 19, 'خو خدای وویل: «نه، خو ستا ښځه ساره به ستا دپاره زوی راوړي او ته به په هغه باندې اسحاق نوم کېږدې. زه به ستا د زوی اسحاق سره خپل لوظ ټینګ وساتم، ترڅو د هغه څخه وروسته د هغه د نسل دپاره یو ابدي لوظ وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis17_verse_19.mp3', '', 1761754199, 1761754199),
(40097, 'Genesis 17:20', 'Genesis', 17, 20, 'ما د اسماعیل په هکله ستا غوښتنه واورېدله. نو زه به هغه ته هم برکت ورکړم او هغه ته به زیات ماشومان او ډېره اولاده ورکړم. هغه به د دولسو زامنو پلار وي چې مشران به وي او زه به د هغه د اولادې څخه یو لوی قوم جوړ کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis17_verse_20.mp3', '', 1761754199, 1761754199),
(40098, 'Genesis 17:21', 'Genesis', 17, 21, 'خو خپل لوظ به ستا د زوی اسحاق سره چې ساره به یې په راتلونکي کال کې په همدې وخت وزېږوي، ټینګ وساتم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis17_verse_21.mp3', '', 1761754199, 1761754199),
(40099, 'Genesis 17:22', 'Genesis', 17, 22, 'کله چې خدای د ابراهیم سره خپلې خبرې خلاصې کړې، نو د هغه څخه لاړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis17_verse_22.mp3', '', 1761754199, 1761754199),
(40100, 'Genesis 17:23', 'Genesis', 17, 23, 'ابراهیم خپل زوی اسماعیل او نور ټول نارینه چې د هغه په کورنۍ کې وو او هغه غلامان چې د هغه په کورنۍ کې زېږېدلي وو او هغه غلامان چې په پیسو باندې اخیستل شوي وو لکه څنګه چې خدای هغه ته ویلي وو، په هماغه ورځ سنت کړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis17_verse_23.mp3', '', 1761754199, 1761754199),
(40101, 'Genesis 17:24', 'Genesis', 17, 24, 'ابراهیم د نهه نوي کالو په عمر ؤ چې سنت کړای شو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis17_verse_24.mp3', '', 1761754199, 1761754199),
(40102, 'Genesis 17:25', 'Genesis', 17, 25, 'او د هغه زوی اسماعیل د دیارلسو کالو په عمر ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis17_verse_25.mp3', '', 1761754199, 1761754199),
(40103, 'Genesis 17:26', 'Genesis', 17, 26, 'ابراهیم او د هغه زوی اسماعیل دواړه په یوه ورځ سنت شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis17_verse_26.mp3', '', 1761754199, 1761754199),
(40104, 'Genesis 17:27', 'Genesis', 17, 27, 'د ابراهیم د کورنۍ هر نارینه او هغه غلامان چې د هغوی په کورنۍ کې زېږېدلي وو یا هغوی چې په پیسو اخیستل شوي وو، د هغه سره یوځای سنت شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis17_verse_27.mp3', '', 1761754199, 1761754199),
(40105, 'Genesis 20:1', 'Genesis', 20, 1, 'ابراهیم د ممري څخه د کنعان جنوب خواته کډه وکړه او د قادش او شور په منځ کې یې اوسېده او د یو څه وخت دپاره په جرار کې پاتې شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis20_verse_1.mp3', '', 1761754199, 1761754199),
(40106, 'Genesis 20:2', 'Genesis', 20, 2, 'هلته ابراهیم د خپلې ښځې ساره په هکله وویل: «هغه زما خور ده.» د جرار پاچا ابي‌ملک په ساره پسې کسان ولېږل او هغه یې راوستله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis20_verse_2.mp3', '', 1761754199, 1761754199),
(40107, 'Genesis 20:3', 'Genesis', 20, 3, 'یوه شپه خدای په خوب کې ابي‌ملک ته ښکاره شو او ویې ویل: «ته به مړ شې، ځکه هغه ښځه چې تا خپل ځان ته راوستلې ده، هغه واده شوې ښځه ده.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis20_verse_3.mp3', '', 1761754199, 1761754199),
(40108, 'Genesis 20:4', 'Genesis', 20, 4, 'خو ابي‌ملک لا هغې ته ورنژدې شوی نه ؤ، هغه وویل: «ای څښتنه، ایا ته به بې‌ګناه خلک ووژنې؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis20_verse_4.mp3', '', 1761754199, 1761754199),
(40109, 'Genesis 20:5', 'Genesis', 20, 5, 'ابراهیم په خپله وویل چې هغه زما خور ده او هغې هم همدا خبره وکړه چې دی زما ورور دی او دا کار ما د پاک وجدان له مخې کړی دی او هېڅ غلطي مې نه ده کړې.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis20_verse_5.mp3', '', 1761754199, 1761754199),
(40110, 'Genesis 20:6', 'Genesis', 20, 6, 'خدای په خوب کې هغه ته وویل: «هو، زه پوهېږم چې تا دا کار د پاک وجدان له مخې کړی دی او ته مې د دې څخه وساتلې چې زما په وړاندې کومه ګناه وکړې او دې ته مې پرېنښودلې چې هغې ته لاس وروړې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis20_verse_6.mp3', '', 1761754199, 1761754199);